package main

import (
	"fmt"
	"go/ast"
	"go/parser"
	"go/token"
	"io/ioutil"
	"os"

	"github.com/mwitkow/go-avro/schema"
)

func parseGoFile(filePath string) (schema.Schema, error) {
	fileBytes, err := ioutil.ReadFile(filePath)
	if err != nil {
		return nil, fmt.Errorf("failed to read file: %w", err)
	}

	var tree ast.File
	err = parser.ParseFile(&tree, "", string(fileBytes), 0)
	if err != nil {
		return nil, fmt.Errorf("failed to parse file: %w", err)
	}

	structName := ""
	for _, decl := range tree.Decls {
		switch d := decl.(type) {
		case *ast.StructType:
			structName = d.Name.Name
			break
		default:
			continue
		}
	}

	if structName == "" {
		return nil, fmt.Errorf("no struct found in file")
	}

	// Create an empty schema
	schema := &schema.Schema{
		Name: "struct",
		Type: "record",
	}

	for _, field := range d.Fields.List {
		fieldSchema := &schema.Field{
			Name:   field.Names[0].Value,
			Type:   schema.Type(schema.STRING),
			Optional: false,
		}

		schema.Fields = append(schema.Fields, fieldSchema)
	}

	return schema, nil
}

func main() {
	filePath := os.Args[1]
	structName := os.Args[2]

	schema, err := parseGoFile(filePath)
	if err != nil {
		fmt.Println(err)
		os.Exit(1)
	}

	outputFilePath := filePath + ".avsc"
	f, err := os.Create(outputFilePath)
	if err != nil {
		fmt.Printf("Failed to create output file: %v\n", err)
		os.Exit(1)
	}
	defer f.Close()

	err = json.NewEncoder(f).Encode(structName + "\n" + schema.String())
	if err != nil {
		fmt.Printf("Error encoding schema: %v\n", err)
		os.Exit(1)
	}

	fmt.Printf("Schema generated successfully at: %s\n", outputFilePath)
}
