            $table->id();
            $table->string('name');
            $table->string('email')->unique();

            // Foreign key relationships
            $table->foreignId('house_id')
                  ->nullable()
                  ->constrained()
                  ->onDelete('cascade');

            $table->foreignId('car_id')
                  ->nullable()
                  ->constrained()
                  ->onDelete('set null');

            $table->foreignId('pet_id')
                  ->nullable()
                  ->constrained()
                  ->onDelete('set null');

            // Other base fields (e.g., password, email confirmation)
